#include <list>
#include <chrono>
#include <random>
#include <iostream>
#include <algorithm>

template<typename Container>
double benchmark_middle_insertions(size_t initial_size, size_t num_insertions) {
    std::mt19937 rng(42);
    std::uniform_int_distribution<size_t> pos_dist(0, 1000000);

    Container cont;
    cont.reserve(initial_size);
    for (size_t i = 0; i < initial_size; ++i)
        cont.push_back(i);

    auto start = std::chrono::high_resolution_clock::now();

