## Full Benchmark Code

### Go (`benchmark.go`)
```go
package main

import (
	"fmt"
	"time"
)

func compute() int64 {
	var sum int64
	const iterations = 100_000_000
	for i := int64(0); i < iterations; i++ {
		x := i*3 + 7
		if x%2 == 0 {
			sum += x / 2
		} else {
			sum += x * 2
		}
	}
	return sum
}

func main() {
	// Warm-up
	compute()

	runs := 5
	bestTime := time.Duration(0)

	for r := 0; r < runs; r++ {
		start := time.Now()
		result := compute()
		elapsed := time.Since(start)

		if r == 0 || elapsed < bestTime {
			bestTime = elapsed
		}
		fmt.Printf("Run %d: %v (result: %d)\n", r+1, elapsed, result)
	}
	fmt.Printf("\nBest time: %v\n", bestTime)
}
```

